from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.cu.services.licensed.agent.http_client import AGENTLicensedv1HttpClient


@auto_token_refresh()
class AGENTLicensedv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = AGENTLicensedv1HttpClient(base_url=con_details.base_url,
                                                      connection_alias=con_details.alias)

    def reset_cu(self, timeout):
        return self.local_client.reset_cu(timeout=timeout)
